def analyze_grid(grid, bg):
    # Count by anti-diagonal
    ad_counts = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != bg:
                s = r + c
                if s not in ad_counts:
                    ad_counts[s] = {}
                ad_counts[s][val] = ad_counts[s].get(val, 0) + 1

    # Find anti-diagonals with any value appearing >= 2 times
    result = {}
    for s, vals in ad_counts.items():
        for v, count in vals.items():
            if count >= 2:
                if s not in result:
                    result[s] = v
                elif result[s] != v:
                    raise ValueError(f"Conflicting values on anti-diagonal {s}: {result[s]} vs {v}")
    return result

