# Build expected output
def apply_rule(grid, bg, repeats_map):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for s, v in repeats_map.items():
        for r in range(h):
            c = s - r
            if 0 <= c < w:
                result[r][c] = v

    return result

