def solve_anti_diag(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Step 1: Find global background (most frequent value)
    cnt_global = Counter()
    for r in range(h):
        for c in range(w):
            cnt_global[grid[r][c]] += 1
    bg = max(cnt_global.items(), key=lambda x: x[1])[0]

    # Step 2: Build anti-diagonals and find candidates
    ad_data = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            s = r + c
            if s not in ad_data:
                ad_data[s] = []
            ad_data[s].append(v)

    # Step 3: For each anti-diagonal, find non-bg values with count >= 2
    candidates = {}  # {sum_value: chosen_fill_value}
    for s, vals in sorted(ad_data.items()):
        cnt = Counter(vals)
        repeats = [(v, count) for v, count in cnt.items() if v != bg and count >= 2]
        if repeats:
            # Pick max value among those appearing >= 2 times
            chosen = max(v for v, _ in repeats)
            candidates[s] = chosen

    # Step 4: Apply fills
    result = [[grid[r][c] for c in range(w)] for r in range(h)]
    for s, fill_val in candidates.items():
        for r in range(h):
            c = s - r
            if 0 <= c < w:
                result[r][c] = fill_val

    return result, candidates, bg

