            if 0 <= c < w:
                v = grid[r][c]
                if v != bg:
                    vals_on_s.append(v)
        cnt = Counter(vals_on_s)
        repeats = [(v, cnt[v]) for v, c in cnt.items() if c == 2]
        if repeats:
            ad_repeats[s] = repeats

    print(f"Anti-diagonals with exactly-2 repeated non-bg: {ad_repeats}")

    # Collect all (diagonal_sum, fill_value) pairs to apply
